/**
 * Demo data for Calimax ERP (database `calimax`).
 *
 * History is generated by running the REAL workflows — purchase order → goods receipt → supplier
 * invoice → sales order → pick → dispatch → delivery → invoice → payment, plus returns, a recall,
 * transfers, adjustments and expenses — so every figure, stock level and ledger entry is consistent.
 *
 *   php database/seed_demo.php
 */
if (PHP_SAPI !== 'cli') { http_response_code(403); exit('Run from the command line.'); }
require_once __DIR__ . '/../includes/bootstrap.php';
if (DB_NAME !== 'calimax') { fwrite(STDERR, "Refusing to seed: DB_NAME is not 'calimax'.\n"); exit(1); }

$pdo = db();
if ((int) $pdo->query('SELECT COUNT(*) FROM products')->fetchColumn() > 0) { fwrite(STDERR, "Demo data already present (products exist). Use install.php --force to rebuild.\n"); exit(1); }
mt_srand(2026);
echo "Seeding demo data…\n";

// ---------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------
function as_user(string $u): void
{
    $s = db()->prepare('SELECT id, username, full_name, email, role, territory_id, is_active FROM users WHERE username = :u'); $s->execute([':u' => $u]);
    $_SESSION['user'] = $s->fetch();
}
function set_day(int $ago): string { return $GLOBALS['__today'] = date('Y-m-d', strtotime("-$ago days")); }
function marks(): array
{
    $m = [];
    foreach (['trace_events', 'stock_movements', 'activity_log', 'journal_entries', 'purchase_orders', 'goods_receipts', 'supplier_invoices', 'supplier_payments', 'sales_orders', 'deliveries', 'sales_invoices', 'customer_payments',
        'credit_notes', 'sales_returns', 'stock_transfers', 'stock_adjustments', 'stock_counts', 'purchase_returns', 'batches', 'serial_numbers', 'batch_recalls', 'warranty_claims', 'expenses'] as $t) {
        $m[$t] = (int) db()->query("SELECT COALESCE(MAX(id),0) FROM `$t`")->fetchColumn();
    }
    return $m;
}
function backdate(array $m, int $ago, string $time = '10:30:00'): void
{
    $ts = date('Y-m-d', strtotime("-$ago days")) . ' ' . $time;
    foreach ($m as $t => $id) {
        $col = $t === 'batch_recalls' ? 'initiated_at' : 'created_at';
        db()->prepare("UPDATE `$t` SET $col = :ts WHERE id > :id")->execute([':ts' => $ts, ':id' => $id]);
    }
    foreach (['picked_at', 'packed_at', 'dispatched_at', 'delivered_at'] as $c) {
        db()->prepare("UPDATE deliveries SET `$c` = :ts WHERE id > :id AND `$c` IS NOT NULL")->execute([':ts' => $ts, ':id' => $m['deliveries']]);
    }
    db()->prepare('UPDATE purchase_orders SET approved_at = IF(approved_at IS NULL, NULL, :ts) WHERE id > :id')->execute([':ts' => $ts, ':id' => $m['purchase_orders']]);
    db()->prepare('UPDATE sales_orders SET approved_at = IF(approved_at IS NULL, NULL, :ts) WHERE id > :id')->execute([':ts' => $ts, ':id' => $m['sales_orders']]);
}
/** Run a closure as of N days ago, then back-date everything it created. */
function on_day(int $ago, string $user, callable $fn, string $time = '10:30:00')
{
    set_day($ago); as_user($user); $m = marks();
    $r = $fn();
    backdate($m, $ago, $time);
    return $r;
}
function pid(string $code): int { $s = db()->prepare('SELECT id FROM products WHERE code = :c'); $s->execute([':c' => $code]); return (int) $s->fetchColumn(); }
function cid(string $code): int { $s = db()->prepare('SELECT id FROM customers WHERE code = :c'); $s->execute([':c' => $code]); return (int) $s->fetchColumn(); }
function sid(string $code): int { $s = db()->prepare('SELECT id FROM suppliers WHERE code = :c'); $s->execute([':c' => $code]); return (int) $s->fetchColumn(); }
function whid(string $code): int { $s = db()->prepare('SELECT id FROM warehouses WHERE code = :c'); $s->execute([':c' => $code]); return (int) $s->fetchColumn(); }
function factor_of(int $productId, ?string $pack): int
{
    if (!$pack) return 1;
    $s = db()->prepare('SELECT factor FROM product_units WHERE product_id = :p AND name = :n'); $s->execute([':p' => $productId, ':n' => $pack]);
    return (int) ($s->fetchColumn() ?: 1);
}
function items_for(array $lines): array
{
    $out = [];
    foreach ($lines as [$code, $qty, $pack]) {
        $p = pid($code); $f = factor_of($p, $pack);
        $base = db()->prepare('SELECT base_unit FROM products WHERE id = :id'); $base->execute([':id' => $p]);
        $out[] = ['product_id' => $p, 'pack_name' => $pack ?: $base->fetchColumn(), 'pack_factor' => $f, 'pack_qty' => $qty, 'discount_pct' => 0];
    }
    return $out;
}

/** Purchase: PO → approval → GRN (with batches / serials) → supplier invoice → optional payment. */
function buy(int $day, string $supplier, string $wh, array $lines, array $o = []): array
{
    $items = []; $grnLines = [];
    set_day($day); as_user('sanduni'); $m = marks();
    foreach ($lines as $l) {
        $p = pid($l['code']); $f = factor_of($p, $l['pack'] ?? null);
        $base = db()->prepare('SELECT base_unit FROM products WHERE id = :id'); $base->execute([':id' => $p]);
        $items[] = ['product_id' => $p, 'pack_name' => ($l['pack'] ?? null) ?: $base->fetchColumn(), 'pack_factor' => $f, 'pack_qty' => $l['qty'] / $f, 'unit_cost' => $l['cost'] * $f];
    }
    $poId = po_save(null, ['supplier_id' => sid($supplier), 'warehouse_id' => whid($wh), 'order_date' => set_day($day), 'expected_date' => date('Y-m-d', strtotime(set_day($day) . ' +2 days')), 'notes' => null], $items);
    $st = po_submit($poId);
    if ($st === 'pending_approval' && empty($o['leave_pending'])) { as_user('ayesha'); po_decide($poId, true, 'Approved'); as_user('sanduni'); }
    if (!empty($o['leave_draft'])) { /* keep submitted state only */ }
    $st = db()->query("SELECT status FROM purchase_orders WHERE id = $poId")->fetchColumn();
    if ($st === 'approved') po_mark_sent($poId);
    backdate($m, $day, '09:00:00');
    $res = ['po' => $poId, 'grn' => null, 'bill' => null];
    if (isset($o['receive_day']) && in_array($st, ['approved', 'sent'], true)) {
        $res['grn'] = on_day($o['receive_day'], 'mahesh', function () use ($lines, $poId, $supplier, $wh, $o) {
            $poItems = db()->query('SELECT * FROM purchase_order_items WHERE po_id = ' . $poId . ' ORDER BY id')->fetchAll();
            $gl = [];
            foreach ($lines as $i => $l) {
                $p = pid($l['code']);
                $g = ['po_item_id' => $poItems[$i]['id'], 'product_id' => $p, 'qty_received' => $l['recv'] ?? $l['qty'], 'qty_rejected' => $l['rej'] ?? 0, 'reject_reason' => $l['rej_reason'] ?? null, 'unit_cost' => $l['cost']];
                if (!empty($l['batches'])) {
                    $g['batches'] = array_map(fn($b) => ['batch_no' => $b[0], 'qty' => $b[1], 'mfg_date' => date('Y-m-d', strtotime(app_today() . ' -' . ($b[3] ?? 3) . ' days')),
                        'expiry_date' => $b[2] === null ? '' : date('Y-m-d', strtotime(($b[4] ?? false) ? $b[2] : (date('Y-m-d') . ' ' . $b[2]))) ], $l['batches']);
                }
                if (!empty($l['serials'])) $g['serials'] = $l['serials'];
                $gl[] = $g;
            }
            return grn_post(['po_id' => $poId, 'supplier_id' => sid($supplier), 'warehouse_id' => whid($wh), 'received_date' => app_today(), 'supplier_ref' => 'DN-' . mt_rand(10000, 99999), 'notes' => $o['grn_note'] ?? null], $gl);
        }, '11:15:00');
        if (!empty($o['bill'])) {
            $res['bill'] = on_day($o['receive_day'] - ($o['bill_lag'] ?? 1) > 0 ? $o['receive_day'] - ($o['bill_lag'] ?? 1) : 0, 'ayesha', function () use ($res, $supplier, $o) {
                $g = db()->query('SELECT * FROM goods_receipts WHERE id = ' . $res['grn'])->fetch();
                $sub = (float) $g['total_value'] + ($o['bill_variance'] ?? 0);
                $tax = (float) $g['tax_value'];
                return supplier_bill_create(['supplier_id' => sid($supplier), 'supplier_ref' => 'INV/' . mt_rand(1000, 9999), 'invoice_date' => app_today(), 'subtotal' => $sub, 'tax_total' => $tax, 'po_id' => null, 'notes' => null], [$res['grn']]);
            }, '14:00:00');
        }
    }
    return $res;
}

/** Sell: SO → (approval) → delivery → pick → dispatch → confirm → invoice → payment. Returns ids. */
function sell(int $day, string $customer, array $lines, array $o = []): array
{
    $cust = cid($customer);
    $repUser = db()->query('SELECT u.username FROM customers c JOIN users u ON u.id = c.rep_id WHERE c.id = ' . $cust)->fetchColumn() ?: 'nimal';
    set_day($day); as_user($repUser); $m = marks();
    $c = db()->query('SELECT payment_terms_days, credit_limit FROM customers WHERE id = ' . $cust)->fetch();
    $type = $o['type'] ?? ((int) $c['payment_terms_days'] > 0 ? 'credit' : 'cash');
    $soId = so_save(null, ['customer_id' => $cust, 'warehouse_id' => whid($o['wh'] ?? 'COL'), 'order_date' => app_today(), 'required_date' => date('Y-m-d', strtotime(app_today() . ' +1 day')), 'payment_type' => $type,
        'customer_po_ref' => $o['po_ref'] ?? null, 'notes' => $o['notes'] ?? null], items_for($lines));
    $st = so_submit($soId);
    if ($st === 'pending_approval') {
        if (!empty($o['leave_pending'])) { backdate($m, $day, '09:20:00'); return ['so' => $soId]; }
        as_user('nimal'); so_decide($soId, true, 'Approved credit exception — good payment history');
    }
    backdate($m, $day, '09:20:00');
    $res = ['so' => $soId];
    if (!empty($o['stop']) && $o['stop'] === 'confirmed') return $res;
    return $res + on_day($day, 'mahesh', function () use ($soId, $o, $cust, $day) {
        $qtys = [];
        $bal = so_line_balances($soId);
        foreach ($bal as $i => $b) { $qtys[$b['id']] = isset($o['part'][$i]) ? (int) $o['part'][$i] : $b['to_plan']; }
        $dn = delivery_create($soId, $qtys);
        $out = ['dn' => $dn];
        if (($o['stop'] ?? '') === 'pending_pick') return $out;
        pick_auto($dn, $o['serials'] ?? []);
        if (($o['stop'] ?? '') === 'picked') return $out;
        delivery_pack($dn);
        if (($o['stop'] ?? '') === 'packed') return $out;
        $drv = db()->query('SELECT id FROM drivers ORDER BY RAND(' . $day . ') LIMIT 1')->fetchColumn(); $veh = db()->query('SELECT id FROM vehicles ORDER BY RAND(' . $day . ') LIMIT 1')->fetchColumn();
        delivery_dispatch($dn, (int) $drv, (int) $veh);
        if (($o['stop'] ?? '') === 'dispatched') return $out;
        if (!empty($o['fail'])) { delivery_fail($dn, $o['fail']); return $out; }
        $results = [];
        foreach (db()->query('SELECT di.id, p.code, p.tracking FROM delivery_items di JOIN products p ON p.id = di.product_id WHERE di.delivery_id = ' . $dn)->fetchAll() as $di) {
            if (isset($o['reject'][$di['code']])) {
                if ($di['tracking'] === 'serial') {
                    $sr = db()->query('SELECT serial_id FROM delivery_allocations WHERE delivery_item_id = ' . $di['id'] . ' LIMIT ' . (int) $o['reject'][$di['code']][0])->fetchAll(PDO::FETCH_COLUMN);
                    $results[$di['id']] = ['serial_rejects' => $sr, 'reason' => $o['reject'][$di['code']][1]];
                } else $results[$di['id']] = ['rejected' => $o['reject'][$di['code']][0], 'reason' => $o['reject'][$di['code']][1]];
            }
        }
        delivery_confirm($dn, $results, 'Store keeper', 'Signed delivery note', true);
        $out['inv'] = null;
        if (empty($o['no_invoice'])) {
            as_user('ayesha');
            $out['inv'] = invoice_create_from_delivery($dn, app_today(), $o['method'] ?? 'cash');
        }
        return $out;
    }, '15:40:00') + [];
}

/** Auto-pick: FEFO/FIFO suggestions for batch items, first available serials, plain qty otherwise. $serialMap = [product code => [serial nos]] */
function pick_auto(int $dn, array $serialMap = []): void
{
    $del = db()->query('SELECT * FROM deliveries WHERE id = ' . $dn)->fetch();
    $picks = [];
    foreach (db()->query('SELECT di.*, p.tracking, p.code FROM delivery_items di JOIN products p ON p.id = di.product_id WHERE di.delivery_id = ' . $dn)->fetchAll() as $it) {
        $q = (int) $it['qty_planned'];
        if ($it['tracking'] === 'serial') {
            $ids = [];
            if (!empty($serialMap[$it['code']])) {
                foreach ($serialMap[$it['code']] as $sn) { $x = db()->prepare('SELECT id FROM serial_numbers WHERE product_id = :p AND serial_no = :s'); $x->execute([':p' => $it['product_id'], ':s' => $sn]); $ids[] = (int) $x->fetchColumn(); }
            } else $ids = array_map(fn($r) => (int) $r['id'], array_slice(available_serials((int) $it['product_id'], (int) $del['warehouse_id'], $q), 0, $q));
            $picks[$it['id']] = ['serials' => $ids];
        } elseif ($it['tracking'] === 'batch') {
            [$alloc] = suggest_batch_allocation((int) $it['product_id'], (int) $del['warehouse_id'], $q, $dn);
            $picks[$it['id']] = ['batches' => array_column($alloc, 'qty', 'batch_id')];
        } else { $on = (int) db()->query('SELECT COALESCE(on_hand,0) FROM stock WHERE batch_id = 0 AND product_id = ' . (int) $it['product_id'] . ' AND warehouse_id = ' . (int) $del['warehouse_id'])->fetchColumn(); $picks[$it['id']] = ['qty' => min($q, $on)]; }
    }
    delivery_pick($dn, $picks);
}

function pay(int $invoiceId, int $dayPaid, float $amount, string $method = 'bank_transfer'): void
{
    $inv = db()->query('SELECT * FROM sales_invoices WHERE id = ' . $invoiceId)->fetch();
    on_day($dayPaid, 'ayesha', fn() => customer_payment_record((int) $inv['customer_id'], $amount, $method, app_today(), 'REF' . mt_rand(1000, 9999), (int) $inv['rep_id'] ?: null, null, [$invoiceId => $amount]), '16:20:00');
}

