// Generated trading history across the territories
$names = ['C001', 'C002', 'C003', 'C004', 'C007', 'C008', 'C009', 'C010', 'C011', 'C012'];
$mix = [
    [['COKE001', 20, 'Carton'], ['SPR001', 8, 'Carton']], [['WATER001', 30, 'Carton'], ['COKE001', 10, 'Carton']], [['BISC001', 12, 'Carton'], ['SOAP001', 6, 'Carton']],
    [['RICE005', 20, 'Sack of 10']], [['CEM050', 2, 'Pallet']], [['PARA500', 3, 'Box'], ['SOAP001', 4, 'Carton']], [['COKE001', 30, 'Carton'], ['WATER001', 20, 'Carton'], ['SPR001', 15, 'Carton']],
    [['BISC001', 20, 'Carton']], [['RICE005', 40, 'Sack of 10'], ['BISC001', 6, 'Carton']], [['JUICE001', 25, 'Carton'], ['COKE001', 12, 'Carton']],
];
$reliability = ['C001' => 0.7, 'C002' => 0.9, 'C003' => 0.5, 'C004' => 0.85, 'C007' => 0.8, 'C008' => 0.9, 'C009' => 0.95, 'C010' => 0.45, 'C011' => 0.75, 'C012' => 1.0];
$generated = 0;
foreach (range(47, 4, -1) as $day) {
    if ($day % 2 === 1 && mt_rand(0, 3) === 0) continue;
    $c = $names[array_rand($names)];
    $lines = $mix[array_rand($mix)];
    if ($c === 'C012' && mt_rand(0, 1)) $lines = [['COKE001', 5, 'Carton'], ['WATER001', 5, 'Carton']];
    if ($c === 'C004') $lines = [['CEM050', mt_rand(1, 3), 'Pallet']];
    if ($c === 'C009') $lines = [['PARA500', mt_rand(1, 4), 'Box'], ['SOAP001', 3, 'Carton']];
    $wh = in_array($c, ['C007', 'C008', 'C009'], true) ? 'GAM' : (in_array($c, ['C010', 'C011'], true) ? 'KAL' : 'COL');
    // Gampaha / Kalutara hold limited lines — keep their orders to what was transferred there.
    if ($wh === 'GAM') $lines = [['COKE001', mt_rand(3, 9), 'Carton'], ['WATER001', mt_rand(3, 9), 'Carton'], ['RICE005', 3, 'Sack of 10']];
    if ($wh === 'KAL') $lines = [['COKE001', mt_rand(3, 8), 'Carton'], ['WATER001', mt_rand(3, 8), 'Carton']];
    if ($c === 'C012') { $wh = 'COL'; }
    try {
        $r = sell($day, $c, $lines, ['wh' => $wh]);
        $generated++;
        if (!empty($r['inv'])) {
            $inv = db()->query('SELECT total, payment_type FROM sales_invoices WHERE id = ' . $r['inv'])->fetch();
            if ($inv['payment_type'] === 'credit' && mt_rand(0, 100) < $reliability[$c] * 100) {
                $terms = (int) db()->query('SELECT payment_terms_days FROM customers WHERE id = ' . cid($c))->fetchColumn();
                $payDay = $day - mt_rand(max(3, $terms - 10), $terms + 8);
                if ($payDay >= 0) pay($r['inv'], $payDay, round((float) $inv['total'] * (mt_rand(0, 4) === 0 ? 0.6 : 1), 2), ['bank_transfer', 'cheque', 'cash'][mt_rand(0, 2)]);
            }
        }
    } catch (RuntimeException $e) { echo "   (skipped $c on day -$day: " . $e->getMessage() . ")\n"; }
}
