    $b = (int) db()->query("SELECT id FROM batches WHERE batch_no = 'BATCH-001'")->fetchColumn();
    $rid = recall_start($b, 'Manufacturer reported a contamination issue with this production batch');
    foreach (db()->query("SELECT customer_id FROM recall_customers WHERE recall_id = $rid")->fetchAll(PDO::FETCH_COLUMN) as $cu) recall_mark_contacted($rid, (int) $cu, 'Phoned the store manager');
    $abc = cid('C001');
    recall_record_recovery($rid, $abc, 500, whid('COL'), 'Collected by driver Sunil');
});
